// Select report 136 attachments and hand the CSV to the HTTP node as TEXT.
//
// LP CSV attachments are named `_<YYMMDDHHMMSS>_Export.csv` and carry NO report
// id, so the `_136_` filename test this node used to apply could never match.
// Every attachment was dropped and the workflow completed having done nothing —
// no 136 ingest ran between 2026-08-06 and the 2026-08-10 cutover. Report
// identity is decided by LP-MCP's header fingerprint; scope comes from the
// Gmail subject query.
//
// The ingest route requires the raw CSV text as the request body. n8n's binary
// body mode sends multipart and overrides Content-Type, which the route rejects
// with 400 "POST the CSV text as the request body". So decode to a string here.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary ?? {};
  for (const key of Object.keys(bin)) {
    const fileName = bin[key]?.fileName ?? '';
    if (!/\.csv$/i.test(fileName)) continue;
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    out.push({
      json: {
        lp_report_id: '136',
        attachment_file_name: fileName,
        csv_text: buf.toString('utf8'),
      },
    });
  }
}
return out;
